<script setup lang="ts">
const { user, login, load } = useAuth(); const route=useRoute(); const email=ref(''),password=ref(''),loading=ref(false),error=ref(''); onMounted(async()=>{if(await load())navigateTo('/profile')}); async function submit(){loading.value=true;error.value='';try{await login(email.value,password.value);await navigateTo(String(route.query.redirect||'/profile'))}catch(e:any){error.value=e?.data?.statusMessage||'Connexion impossible'}finally{loading.value=false}};useSeoMeta({title:'Connexion'})
</script>
<template><main class="auth-page page-top"><section class="auth-card"><p class="eyebrow">VOTRE ESPACE</p><h1>Content de vous revoir.</h1><p>Connectez-vous pour synchroniser favoris, historique et préférences.</p><form @submit.prevent="submit"><label>Email<input v-model="email" type="email" autocomplete="email" required></label><label>Mot de passe<input v-model="password" type="password" autocomplete="current-password" required></label><NuxtLink class="auth-forgot" to="/forgot-password">Mot de passe oublié ?</NuxtLink><p v-if="error" class="auth-error">{{ error }}</p><button class="btn btn--primary" :disabled="loading">{{ loading?'Connexion…':'Se connecter' }}</button></form><p>Pas encore de compte ? <NuxtLink to="/register">Créer un compte</NuxtLink></p></section></main></template>
